    for (int k = 0; k < NSOIL; ++k) etrani[k] = K_ZERO;               // :6107
    float snoflow = K_ZERO;                                          // :6108
    float runsub  = K_ZERO;                                          // :6109
    float runsrf  = K_ZERO;                                          // :6110
    float qinsur  = K_ZERO;                                          // :6111
    float qtldrn  = K_ZERO;                                          // :6112
